import{_ as n,C as s,o as i,c as l,E as t,a2 as o}from"./chunks/framework.Cm6XCzck.js";const v=JSON.parse('{"title":"OpenHands Agent Canvas — 工程分析","description":"","frontmatter":{"title":"OpenHands Agent Canvas — 工程分析","date":"2026-08-01","column":"open-source-engineering","category":"daily","summary":"围绕 Skill、连接健康、自动触发、Runtime 选择与操作者体验的工程对标。","outline":"deep","cover":"/assets/covers/openhands-agent-canvas-cover-v2.jpg"},"headers":[],"relativePath":"zh/engineering/openhands.md","filePath":"zh/engineering/openhands.md","lastUpdated":1787407830000}'),r={name:"zh/engineering/openhands.md"};function p(d,a,c,h,u,g){const e=s("ArticleCover");return i(),l("div",null,[t(e,{image:"/assets/covers/openhands-agent-canvas-cover-v2.jpg",kicker:"开源工程观察",title:"OpenHands Agent Canvas",summary:"围绕 Skill、连接健康、自动触发、Runtime 选择与操作者体验的工程对标。",version:"研究专题",status:"持续维护",languageHref:"/en/engineering/openhands",languageLabel:"English"}),a[0]||(a[0]=o(`<h2 id="工程方向" tabindex="-1">工程方向 <a class="header-anchor" href="#工程方向" aria-label="Permalink to &quot;工程方向&quot;">​</a></h2><p>OpenHands 正从 Coding Agent 项目演进为面向操作者的 Agent 工作空间。Agent Canvas 强调自托管、Skill 与 Plugin、连接健康、桌面封装、自动触发和多执行环境。</p><h2 id="runtime-模式" tabindex="-1">Runtime 模式 <a class="header-anchor" href="#runtime-模式" aria-label="Permalink to &quot;Runtime 模式&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent Harness</span></span>
<span class="line"><span>  + Skill 与 Plugin</span></span>
<span class="line"><span>  + 连接健康</span></span>
<span class="line"><span>  + 本地 / 远程 Runtime</span></span>
<span class="line"><span>  + 手动 / 定时 / 事件触发</span></span>
<span class="line"><span>  + 操作者控制台</span></span></code></pre></div><p>长期 AI 工作需要的不只是模型能力，还包括部署可见、可重启、健康状态、工具封装和人类操作界面。</p><h2 id="值得跟踪的能力" tabindex="-1">值得跟踪的能力 <a class="header-anchor" href="#值得跟踪的能力" aria-label="Permalink to &quot;值得跟踪的能力&quot;">​</a></h2><ul><li>Skill 安装、激活与验证分离；</li><li>Plugin 内容可见；</li><li>连接健康诊断；</li><li>启动和运行日志；</li><li>桌面与自托管体验；</li><li>定时和事件触发；</li><li>本地、托管和企业 Runtime 选项。</li></ul><h2 id="codeflowmu-应学习什么" tabindex="-1">CodeFlowMu 应学习什么 <a class="header-anchor" href="#codeflowmu-应学习什么" aria-label="Permalink to &quot;CodeFlowMu 应学习什么&quot;">​</a></h2><ol><li><strong>连接健康成为第一等状态。</strong> Provider 和工具失败必须可见、可操作。</li><li><strong>激活生命周期。</strong> 安装 Skill 不等于已经激活并验证。</li><li><strong>操作者诊断。</strong> 启动、Session 与恢复信息不能只存在于原始日志。</li><li><strong>多种触发模式。</strong> 手动、定时和事件触发应共享同一个 WorkOrder 模型。</li><li><strong>自托管路径。</strong> 面向中小企业需要本地优先的部署方式。</li></ol><h2 id="不应照搬什么" tabindex="-1">不应照搬什么 <a class="header-anchor" href="#不应照搬什么" aria-label="Permalink to &quot;不应照搬什么&quot;">​</a></h2><ul><li>把 Agent Workspace 作为产品第一抽象；</li><li>在没有岗位、所有权和完成契约的情况下扩张功能；</li><li>把 Coding 领域假设写进通用 Core；</li><li>在一个界面暴露所有底层实现概念。</li></ul><h2 id="差异化" tabindex="-1">差异化 <a class="header-anchor" href="#差异化" aria-label="Permalink to &quot;差异化&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OpenHands 的主要抽象：</span></span>
<span class="line"><span>Agent 工作空间与自动化</span></span>
<span class="line"><span></span></span>
<span class="line"><span>CodeFlowMu 的目标抽象：</span></span>
<span class="line"><span>岗位 + WorkOrder + 受治理工作流 + Runtime + 证据</span></span></code></pre></div><p>OpenHands 未来可以成为 CodeFlowMu 下层的 Agent Provider 或执行 Harness；Position、TeamPolicy、FCoP 责任、TMPA 证据和完成门禁应保持稳定。</p><h2 id="建议工程响应" tabindex="-1">建议工程响应 <a class="header-anchor" href="#建议工程响应" aria-label="Permalink to &quot;建议工程响应&quot;">​</a></h2><ul><li>在 Runtime 控制台统一 Provider、工具、Session 与 Agent 健康；</li><li>提供重启、重试、释放、切换 Provider 和恢复动作；</li><li>显示实际加载的 Skill 与版本；</li><li>业务语义 Event 与低层日志保持分离；</li><li>不为了追齐其他项目的功能列表而安排开发。</li></ul><h2 id="战略判断" tabindex="-1">战略判断 <a class="header-anchor" href="#战略判断" aria-label="Permalink to &quot;战略判断&quot;">​</a></h2><p>OpenHands 是 Agent 运行工程的重要对标，但不能替代 CodeFlowMu 以岗位为中心的数字员工架构。</p>`,18))])}const k=n(r,[["render",p]]);export{v as __pageData,k as default};
